import{Z as t,e as i,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Campaign Plugin","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/campaign-plugin.md","filePath":"integrations/email-marketing/campaign-plugin.md","lastUpdated":null}'),o={name:"integrations/email-marketing/campaign-plugin.md"};function r(s,e,l,g,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="campaign-plugin" tabindex="-1">Campaign Plugin <a class="header-anchor" href="#campaign-plugin" aria-label="Permalink to &quot;Campaign Plugin&quot;">​</a></h1><p>The <a href="https://plugins.craftcms.com/campaign" target="_blank" rel="noreferrer">Campaign Plugin</a> requires no setup or settings, other than having the plugin installed and active.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Campaign as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-form-setting" tabindex="-1">Step 2. Form Setting <a class="header-anchor" href="#step-2-form-setting" aria-label="Permalink to &quot;Step 2. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',9)])])}const d=t(o,[["render",r]]);export{m as __pageData,d as default};
